insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"adjectives_mastery_homework_q01_finish","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\adjectives_mastery_homework.yaml","source_metadata":{}},{"key":"adjectives_mastery_homework_q01_start","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\adjectives_mastery_homework.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"adjectives_mastery_homework_q01_finish","locale":"he","line_order":0,"content":"הכרטיסים שלכם והכרטיסים שלי זהים. עכשיו גם אני מאסטרית של שמות תואר, בזכותכם.","line_format":"plain_text"},{"dialogue_key":"adjectives_mastery_homework_q01_finish","locale":"he","line_order":1,"content":"זכרו: שם התואר בא לפני שם העצם. a sharp sword = חרב חדה.","line_format":"plain_text"},{"dialogue_key":"adjectives_mastery_homework_q01_finish","locale":"he","line_order":2,"content":"סיומת er אומרת יותר: dark = חשוך, darker than day = חשוך יותר מיום.","line_format":"plain_text"},{"dialogue_key":"adjectives_mastery_homework_q01_finish","locale":"he","line_order":3,"content":"כל הכבוד, מאסטרים. עשיתם את שיעורי הבית לבד.","line_format":"plain_text"},{"dialogue_key":"adjectives_mastery_homework_q01_start","locale":"he","line_order":0,"content":"שלום שוב, מאסטרים של שמות תואר! אחרי שהפכתם למאסטרים לפניי, רצתי ללמוד כל הלילה.","line_format":"plain_text"},{"dialogue_key":"adjectives_mastery_homework_q01_start","locale":"he","line_order":1,"content":"עכשיו אני רוצה לבדוק את עצמי. כתבו כרטיסי תשובות ושימו אותם בתיבה ליד העץ הגדול, ואני אשווה אותם לכרטיסים שלי.","line_format":"plain_text"},{"dialogue_key":"adjectives_mastery_homework_q01_start","locale":"he","line_order":2,"content":"היום אין שום דבר חדש. אתם המאסטרים, אז כתבו את הכרטיסים לבד, בלי עזרה.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
